import {loadImageAsset} from './asset-loader.js';
import {reportAssetFailure,reportAssetSuccess} from './asset-recovery.js';
// Read-only service scenery. No game state, transactions, storage, timers or RNG.
const supported=new Set(['forge','merchant']);
function sceneFiles(manifest,scene){const layers=manifest?.scenes?.[scene]?.layers;if(!Array.isArray(layers)||!layers.length)return null;const files=[];for(const layer of layers){if(layer.background){const bg=manifest.backgrounds?.find(b=>b.id===layer.background);if(!bg?.file)return null;files.push(bg.file);}else{const sprite=manifest.sprites?.[layer.sprite];if(!sprite?.frames?.length||!sprite.anchor||!layer.at)return null;files.push(...sprite.frames.map(f=>f.file));}}return [...new Set(files)];}
function notice(canvas,label){if(!canvas?.getContext)return false;canvas.width=960;canvas.height=320;const c=canvas.getContext('2d');c.imageSmoothingEnabled=false;c.fillStyle='#122232';c.fillRect(0,0,960,320);c.strokeStyle='#536b80';c.lineWidth=4;c.strokeRect(12,12,936,296);c.fillStyle='#e5c78d';c.font='24px sans-serif';c.textAlign='center';c.fillText(label,480,170,880);return true;}
export function drawPixelServiceScene(canvas,scene,{manifest,images,time=0}={}){
 const files=sceneFiles(manifest,scene);if(!files||files.some(file=>!images?.has(file)))return false;
 if(canvas.width!==960)canvas.width=960;if(canvas.height!==320)canvas.height=320;const c=canvas.getContext('2d');c.imageSmoothingEnabled=false;c.clearRect(0,0,960,320);
 for(const layer of [...manifest.scenes[scene].layers].sort((a,b)=>a.z-b.z)){if(layer.background){const bg=manifest.backgrounds.find(b=>b.id===layer.background);c.drawImage(images.get(bg.file),0,0,960,320);}else{const sprite=manifest.sprites[layer.sprite],ids=sprite.animations?.idle??[sprite.frames[0].id],id=ids[Math.floor(Math.max(0,time)/1000)%ids.length],frame=sprite.frames.find(f=>f.id===id)??sprite.frames[0],size=sprite.frameSize??[192,192];c.drawImage(images.get(frame.file),(layer.at[0]-sprite.anchor[0])*2,(layer.at[1]-sprite.anchor[1])*2,size[0]*2,size[1]*2);}}
 return true;
}
export function createPixelServiceScenes({assetRoot='./service-assets/',onStatus,manifest:providedManifest=null,images:providedImages=null}={}){
 const controller=new AbortController();let manifest=providedManifest,manifestPromise=null,disposed=false;const images=providedImages??new Map(),states=new Map(),pending=new Map();
 function status(scene){if(disposed)return {mode:'disposed',reason:'disposed',label:'场景已释放'};if(!supported.has(scene))return {mode:'unavailable',reason:'unknown-scene',label:'场景暂不可用'};const explicit=states.get(scene);if(['loading','failed'].includes(explicit?.mode))return explicit;const files=sceneFiles(manifest,scene);if(files?.every(f=>images.has(f)))return {mode:'ready',reason:null,label:manifest.scenes[scene].label};return explicit??{mode:'idle',reason:'not-loaded',label:'场景素材准备中'};}
 function publish(scene,value){states.set(scene,value);try{onStatus?.(scene,status(scene));}catch{/* UI listeners must not poison resource state. */}}
 async function getManifest(){if(manifest)return manifest;if(!manifestPromise)manifestPromise=(async()=>{const response=await fetch(assetRoot+'manifest.json');if(!response.ok)throw Error('Manifest HTTP '+response.status);manifest=await response.json();return manifest;})().finally(()=>{manifestPromise=null;});return manifestPromise;}
 async function load(scene,{retry=false}={}){if(disposed||!supported.has(scene))return false;if(pending.has(scene))return pending.get(scene);if(status(scene).mode==='ready')return true;if(status(scene).mode==='failed'&&!retry)return false;publish(scene,{mode:'loading',reason:'loading',label:'场景素材加载中'});
 const promise=(async()=>{await Promise.resolve();try{if(typeof globalThis.fetch!=='function'&&!manifest||typeof globalThis.Image!=='function'&&!providedImages)throw Error('Image/fetch unavailable');await getManifest();const files=sceneFiles(manifest,scene);if(!files)throw Error('Scene mapping missing');await Promise.all(files.map(async file=>{if(images.has(file))return;const img=await loadImageAsset(assetRoot+file,{signal:controller.signal,retry:retry?3:0});if(!disposed)images.set(file,img);}));if(disposed)return false;reportAssetSuccess(assetRoot+'manifest.json');publish(scene,{mode:'ready',reason:null,label:manifest.scenes[scene].label});return true;}catch(error){if(!disposed)reportAssetFailure(error.assetUrl??assetRoot+'manifest.json',error);if(!disposed)publish(scene,{mode:'failed',reason:'asset-load-failed',label:'场景加载失败 · 请重试',error:String(error?.message??error)});return false;}finally{pending.delete(scene);}})();pending.set(scene,promise);return promise;}
 function draw(canvas,scene,time=0){if(disposed)return false;const current=status(scene);if(current.mode!=='ready')return notice(canvas,current.label);try{return drawPixelServiceScene(canvas,scene,{manifest,images,time});}catch(error){publish(scene,{mode:'failed',reason:'draw-failed',label:'场景绘制失败 · 请重试',error:String(error?.message??error)});return notice(canvas,'场景绘制失败 · 请重试');}}
 return Object.freeze({load,draw,status,dispose(){disposed=true;controller.abort();states.clear();}});
}
